using System.Threading.Tasks;

class A
{
    static void Main()
    {
        System.Console.WriteLine("Non Task Main");
    }
    async static Task Main(string[] args)
    {
        await Task.Factory.StartNew(() => { });
        System.Console.WriteLine("Task Main");
    }
}

